// Carried from source (transformed for Native)
pub fn integer_sqrt(n: u128) -> u128 {
    if n == 0 {
        return 0;
    }
    let mut x = n;
    let mut y = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    x
}

#[derive(Clone, Copy, Debug, PartialEq)]
#[repr(u32)]
pub enum AmmError {
    /// Invalid fee rate
    InvalidFeeRate = 6000,
    /// Invalid price
    InvalidPrice = 6001,
    /// Invalid amount
    InvalidAmount = 6002,
    /// Pool is frozen
    PoolFrozen = 6003,
    /// Slippage exceeded
    SlippageExceeded = 6004,
    /// Insufficient liquidity
    InsufficientLiquidity = 6005,
    /// Unauthorized
    Unauthorized = 6006,
    /// Arithmetic overflow
    Overflow = 6007,
    /// Arithmetic underflow
    Underflow = 6008,
}

impl From<AmmError> for ProgramError {
    fn from(error: AmmError) -> Self {
        ProgramError::Custom(error as u32)
    }
}

impl std::fmt::Display for AmmError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{:?}", self)
    }
}

impl std::error::Error for AmmError {}